'use strict';
const KEY='xuong-noi-dung-v1', statuses={idea:'Ý tưởng',draft:'Đang viết',review:'Chờ duyệt',approved:'Đã duyệt',live:'Đã đăng'},platforms=['Facebook','Web truyện','Webtoon','TikTok','Pinterest','Etsy','YouTube','Khác'],sources=['Truyện đọc (chương trả phí)','Quảng cáo Facebook','Etsy','Pinterest / Affiliate','Shopee Affiliate','Webtoon','TikTok','YouTube','Ủng hộ / Sao','Khác'];
const templates=[{id:'tpl1',name:'Chương truyện',text:'Viết chương tiếp theo cho {tên truyện}. Dàn ý: {dàn ý}. Bám sát hồ sơ nhân vật và tóm tắt chương trước: {tóm tắt}. Độ dài {số từ} từ. Không thay đổi các sự kiện đã xác lập.'},{id:'tpl2',name:'Teaser Shorts 30–60 giây',text:'Viết kịch bản teaser 30–60 giây về {chủ đề}. Mở đầu thu hút trong 3 giây, chia lời dẫn và hình ảnh theo mốc thời gian, kết thúc bằng lời mời xem nội dung đầy đủ. Không bịa dữ kiện.'},{id:'tpl3',name:'Ghim Pinterest',text:'Viết tiêu đề, mô tả, từ khóa và câu lệnh ảnh tiếng Anh cho ghim Pinterest về {chủ đề}. Ảnh dọc 2:3. Link đích: {link}. Không đưa ra tuyên bố chưa kiểm chứng.'},{id:'tpl4',name:'Mô tả Etsy + 13 tag',text:'Viết tiêu đề, mô tả và đúng 13 tag cho sản phẩm Etsy: {sản phẩm}. Thông số thực tế: {thông số}. Chỉ dùng thông tin đã cung cấp; không dùng nhân vật hoặc thương hiệu của bên khác.'}];
function initial(){return{version:1,channels:[],content:[],prompts:templates.map(x=>({...x})),metrics:[],series:[],sources:[...sources]}}
let db=initial(),loadError=false;try{const s=localStorage.getItem(KEY);if(s){const v=JSON.parse(s);validate(v);db=v}}catch(e){loadError=true}
function validate(v){if(!v||v.version!==1)throw Error('Phiên bản sao lưu không hỗ trợ');for(const k of ['channels','content','prompts','metrics','series','sources'])if(!Array.isArray(v[k]))throw Error('Thiếu dữ liệu '+k);const ids=new Set;for(const k of ['channels','content','prompts','metrics','series'])for(const r of v[k]){if(!r||typeof r.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(r.id)||ids.has(k+r.id))throw Error('ID không hợp lệ');ids.add(k+r.id)}for(const c of v.content)if(!statuses[c.status]||typeof c.title!=='string')throw Error('Nội dung không hợp lệ');for(const m of v.metrics)if(!Number.isFinite(m.revenue)||m.revenue<0||!/^\d{4}-\d{2}-\d{2}$/.test(m.date))throw Error('Số liệu không hợp lệ');for(const s of v.sources)if(typeof s!=='string')throw Error('Nguồn thu không hợp lệ');for(const k of ['assets','workflows']){if(v[k]!==undefined&&!Array.isArray(v[k]))throw Error('Dữ liệu công việc không hợp lệ');for(const r of v[k]||[]){if(!r||typeof r.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(r.id)||typeof r.title!=='string')throw Error('Mục công việc không hợp lệ');if(k==='assets'&&r.data&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(r.data))throw Error('Ảnh sao lưu không hợp lệ');if(k==='workflows'&&(!['pinterest','etsy'].includes(r.type)||!['draft','approved','live'].includes(r.status)))throw Error('Trạng thái công việc không hợp lệ')}}}
let view=location.hash.slice(1)||'overview',filterChannel='',filterStatus='',query='',mode='board',period='month',calendarDate=new Date(),calendarMode='month',editType='',editId='',toastTimer;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n||0).toLocaleString('vi-VN')+' ₫',num=n=>Number(n||0).toLocaleString('vi-VN'),uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join(''),today=()=>{const d=new Date;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},ch=id=>db.channels.find(x=>x.id===id),channelName=id=>ch(id)?.name||'Kênh đã xóa',dateText=s=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleString('vi-VN',s.length===10?{day:'2-digit',month:'2-digit',year:'numeric'}:{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'Chưa xếp lịch';
function toast(s){const t=$('#toast');if($('#editor').open)$('#editor').append(t);else document.body.append(t);t.textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function save(){if(loadError){toast('Dữ liệu cũ bị lỗi. Hãy khôi phục từ bản sao lưu trước khi ghi mới.');return false}try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(e){toast('Không lưu được: bộ nhớ đầy hoặc trình duyệt chặn lưu trữ. Hãy xuất sao lưu ngay.');return false}}
const paths={overview:'M3 10l9-7 9 7v11H3z M9 21v-8h6v8',content:'M5 3h10l4 4v14H5z M9 12h6 M9 16h6',calendar:'M3 5h18v16H3z M3 10h18 M7 3v4 M17 3v4',series:'M12 5C8 2 3 4 3 4v16s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1z M12 5v16',prompts:'M4 4h16v13H9l-5 4z M8 8h8 M8 12h5',metrics:'M4 20v-6h3v6 M11 20V9h3v11 M18 20V3h3v17',channels:'M8 8a3 3 0 1 0 0-1 M17 5a3 3 0 1 0 0-1 M17 19a3 3 0 1 0 0-1 M9 8l6-3 M9 10l6 7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const navs={overview:'Tổng quan',content:'Nội dung',calendar:'Lịch đăng',series:'Bộ truyện',prompts:'Câu lệnh',metrics:'Doanh thu',channels:'Kênh',settings:'Cài đặt'};
function icon(k){return `<span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.content}"></path></svg></span>`}
function opts(arr,val){return arr.map(x=>{let [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(l)}</option>`}).join('')}
function channelOptions(all=true,val=filterChannel){return opts([...(all?[['','Tất cả kênh']]:[]),...db.channels.map(c=>[c.id,c.name])],val)}
function heading(title,subtitle,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${action}</div></div>`}
function empty(title,text,button=''){return `<div class="empty"><div class="empty-symbol">＋</div><h3>${title}</h3><p>${text}</p>${button}</div>`}
function addBtn(type,label){return `<button class="primary" data-new="${type}">+ ${label}</button>`}
function badge(c){const late=c.scheduledAt&&new Date(c.scheduledAt)<new Date&&c.status!=='live';return `<span class="badge ${late?'late':c.status}">${late?'Trễ lịch':statuses[c.status]}</span>`}
function filtered(){return db.content.filter(c=>(!filterChannel||c.channelId===filterChannel)&&(!filterStatus||c.status===filterStatus)&&(!query||(c.title+' '+c.body).toLowerCase().includes(query.toLowerCase())))}
function periodMetrics(){return db.metrics.filter(m=>{if(filterChannel&&m.channelId!==filterChannel)return false;const now=new Date,d=new Date(m.date+'T12:00:00');return period==='all'||(period==='month'?d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear():d.getMonth()===new Date(now.getFullYear(),now.getMonth()-1,1).getMonth()&&d.getFullYear()===new Date(now.getFullYear(),now.getMonth()-1,1).getFullYear())})}
function render(){if(!navs[view])view='overview';$('#nav').innerHTML=Object.entries(navs).map(([k,l],i)=>`<a href="#${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}>${icon(k)}${k!=='settings'?i+1+'. ':''}${l}</a>`).join('');$('#breadcrumb').textContent='Không gian làm việc / '+navs[view];$('#main').innerHTML=({overview:overview,content:contentPage,channels:channelsPage,prompts:promptsPage,metrics:metricsPage,calendar:calendarPage,series:seriesPage,settings:settingsPage,publish:publishPage,tracking:trackingPage,images:imagesPage,pinterest:pinterestPage,etsy:etsyPage}[view])();document.title=navs[view]+' | Xưởng Nội Dung'}
function overview(){const ms=periodMetrics(),rev=ms.reduce((a,m)=>a+m.revenue,0),cs=db.content.filter(c=>!filterChannel||c.channelId===filterChannel),tasks=cs.filter(c=>c.status==='review'||c.scheduledAt&&c.status!=='live').sort((a,b)=>(a.scheduledAt||'z').localeCompare(b.scheduledAt||'z')),review=cs.filter(c=>c.status==='review').length,late=cs.filter(c=>c.scheduledAt&&new Date(c.scheduledAt)<new Date&&c.status!=='live').length;
return heading('Tổng quan','Một nơi để bắt đầu ngày làm nội dung.',`<select aria-label="Lọc kênh" id="channelFilter">${channelOptions()}</select>${addBtn('content','Tạo nội dung')}`)+`<div class="notice"><div><strong>${db.channels.length?'Hôm nay có '+review+' bài chờ duyệt, '+late+' bài trễ lịch.':'Chào mừng đến Xưởng của bạn'}</strong><p>${db.channels.length?'Duyệt nội dung trước khi đưa vào lịch đăng.':'Bắt đầu bằng một kênh, rồi tạo nội dung đầu tiên.'}</p></div>${db.channels.length?'<button data-go="content">Mở nội dung</button>':addBtn('channels','Thêm kênh')}</div><div class="filters"><select id="period" aria-label="Khoảng thời gian">${opts([['month','Tháng này'],['last','Tháng trước'],['all','Tất cả thời gian']],period)}</select><span class="muted">${ms.length?'Số liệu do bạn ghi nhận':'Chưa có số liệu được ghi nhận'}</span></div><div class="stats">${[['Doanh thu',money(rev),'Theo số liệu đã nhập'],['Lượt xem',num(ms.reduce((a,m)=>a+(m.views||0),0)),'Lượt xem tăng thêm'],['Người theo dõi mới',num(ms.reduce((a,m)=>a+(m.followers||0),0)),'Theo số liệu đã nhập'],['Nội dung đã đăng',cs.filter(c=>c.status==='live').length,'Tổng số bài trong kênh đã chọn']].map(([l,n,h])=>`<div class="stat"><span>${l}</span><strong>${n}</strong><small>${h}</small></div>`).join('')}</div><div class="grid two"><section class="panel"><div class="panel-head"><h2>Việc cần xử lý</h2><button data-go="content">Xem tất cả</button></div>${tasks.length?tasks.slice(0,5).map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><small>${esc(channelName(c.channelId))} / ${dateText(c.scheduledAt)}</small></div><div class="actions">${badge(c)}<button data-edit="content" data-id="${c.id}">Mở bài</button></div></div>`).join(''):empty('Chưa có việc chờ xử lý','Bài chờ duyệt và bài đã xếp lịch sẽ xuất hiện tại đây.')}</section><section class="panel"><div class="panel-head"><h2>Tiến độ nội dung</h2><span class="muted">${cs.length} bài</span></div>${Object.entries(statuses).map(([k,l])=>{const n=cs.filter(c=>c.status===k).length;return `<div class="progress-label"><span>${l}</span><strong>${n}</strong></div><div class="progress"><i style="width:${cs.length?n/cs.length*100:0}%"></i></div>`}).join('')}</section></div><div class="grid two mt"><section class="panel"><div class="panel-head"><h2>Doanh thu theo ngày</h2><span>${money(rev)}</span></div>${ms.length?chart(ms):empty('Chưa có doanh thu','Nhập số liệu trong tab Doanh thu để theo dõi hiệu quả.','<button data-go="metrics">Ghi nhận số liệu</button>')}</section><section class="panel"><div class="panel-head"><h2>Hiệu quả theo kênh</h2><button data-go="channels">Quản lý kênh</button></div>${db.channels.length?`<div class="table-wrap"><table><thead><tr><th>Kênh</th><th class="num">Bài đăng</th><th class="num">Doanh thu</th></tr></thead><tbody>${db.channels.filter(c=>!filterChannel||c.id===filterChannel).map(c=>`<tr><td>${esc(c.name)}</td><td class="num">${db.content.filter(x=>x.channelId===c.id&&x.status==='live').length}</td><td class="num">${money(ms.filter(x=>x.channelId===c.id).reduce((s,x)=>s+x.revenue,0))}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có kênh','Thêm kênh để theo dõi tiến độ và hiệu quả.')}</section></div>`}
function chart(ms){let dates=[...new Set(ms.map(m=>m.date))].sort(),values=dates.map(d=>ms.filter(m=>m.date===d).reduce((a,m)=>a+m.revenue,0)),max=Math.max(...values,1);return `<div class="chart" role="img" aria-label="Doanh thu theo từng ngày đã nhập">${values.map((v,i)=>`<div class="bar" style="height:${v/max*100}%" title="${esc(dates[i])}: ${money(v)}"></div>`).join('')}</div><div class="chart-labels"><span>${dateText(dates[0])}</span><span>${dateText(dates.at(-1))}</span></div>`}
function contentPage(){const cs=filtered();return heading('Nội dung','Từ một ý tưởng đến bài viết đã xuất bản.',addBtn('content','Tạo nội dung'))+`<div class="filters"><input id="search" type="search" placeholder="Tìm nội dung…" aria-label="Tìm nội dung" value="${esc(query)}"><select id="channelFilter" aria-label="Lọc kênh">${channelOptions()}</select><select id="statusFilter" aria-label="Lọc trạng thái">${opts([['','Tất cả trạng thái'],...Object.entries(statuses)],filterStatus)}</select><button id="toggleMode">${mode==='board'?'Xem danh sách':'Xem bảng tiến độ'}</button><span class="muted">${cs.length} nội dung</span></div>${!db.channels.length?`<div class="notice"><p>Thêm kênh trước khi tạo nội dung để mỗi bài có đúng ngữ cảnh.</p>${addBtn('channels','Thêm kênh')}</div>`:''}`+(mode==='board'?`<div class="board">${Object.entries(statuses).map(([k,l])=>`<section class="column"><h3>${l}<span class="muted">${cs.filter(c=>c.status===k).length}</span></h3>${cs.filter(c=>c.status===k).map(c=>`<button class="content-card" data-edit="content" data-id="${c.id}"><small>${esc(ch(c.channelId)?.platform||'Khác')}</small><strong>${esc(c.title)}</strong><small>${esc(channelName(c.channelId))}</small><div class="card-foot"><span>${dateText(c.scheduledAt)}</span></div></button>`).join('')}${!cs.some(c=>c.status===k)?'<p class="muted">Chưa có bài</p>':''}</section>`).join('')}</div>`:`<section class="panel">${cs.length?`<div class="table-wrap"><table><thead><tr><th>Tiêu đề</th><th>Kênh</th><th>Trạng thái</th><th>Lịch đăng</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(channelName(c.channelId))}</td><td>${badge(c)}</td><td>${dateText(c.scheduledAt)}</td><td><button data-edit="content" data-id="${c.id}">Mở</button></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có nội dung phù hợp','Tạo bài mới hoặc thay đổi bộ lọc.')}</section>`)}
function channelsPage(){return heading('Kênh','Giữ giọng văn và định hướng riêng cho từng kênh.',addBtn('channels','Thêm kênh'))+(db.channels.length?`<div class="cards">${db.channels.map(c=>`<article class="panel"><span class="channel-mark">${esc(c.platform)}</span><h2>${esc(c.name)}</h2><p>${esc(c.genre||'Chưa có chủ đề')}</p><small>${db.content.filter(x=>x.channelId===c.id).length} nội dung / ${db.series.filter(x=>x.channelId===c.id).length} bộ truyện</small><p>Giọng văn: ${esc(c.style||'Chưa thiết lập')}</p><span class="badge">Đăng thủ công</span><div class="actions"><button data-edit="channels" data-id="${c.id}">Chỉnh sửa</button>${safeLink(c.link,'Mở kênh')}</div></article>`).join('')}</div>`:`<section class="panel">${empty('Kênh đầu tiên của bạn','Thêm Facebook, YouTube, Etsy hoặc một nền tảng bạn đang làm.',addBtn('channels','Thêm kênh'))}</section>`)}
function promptsPage(){return heading('Câu lệnh','Mẫu dùng lại, có thể cá nhân hóa trước khi gửi AI.',addBtn('prompts','Thêm câu lệnh'))+`<div class="cards">${db.prompts.map(p=>`<article class="panel"><h2>${esc(p.name)}</h2><p>${esc(p.text.slice(0,230))}${p.text.length>230?'…':''}</p><div class="actions"><button class="primary" data-use="${p.id}">Dùng mẫu</button><button data-edit="prompts" data-id="${p.id}">Sửa</button></div></article>`).join('')}</div>`}
function seriesPage(){return heading('Bộ truyện','Dàn ý, nhân vật và chương truyện trong cùng một nơi.',addBtn('series','Tạo bộ truyện'))+(db.series.length?`<div class="cards">${db.series.map(s=>{const chapters=db.content.filter(c=>c.seriesId===s.id);return `<article class="panel"><span class="badge">${esc(s.exclusivity||'Không độc quyền')}</span><h2 class="mt">${esc(s.title)}</h2><small>${esc(channelName(s.channelId))}</small><p>${esc((s.outline||'Chưa có dàn ý').slice(0,160))}</p><small>${chapters.length} chương / ${chapters.filter(c=>c.status==='live').length} đã đăng</small><div class="actions"><button class="primary" data-chapter="${s.id}">+ Viết chương</button><button data-edit="series" data-id="${s.id}">Hồ sơ truyện</button></div>${chapters.map(c=>`<div class="row"><span>${esc(c.title)}</span><button data-edit="content" data-id="${c.id}">Mở</button></div>`).join('')}</article>`}).join('')}</div>`:`<section class="panel">${empty('Bắt đầu một bộ truyện','Lưu dàn ý và hồ sơ nhân vật để các chương luôn nhất quán.',addBtn('series','Tạo bộ truyện'))}</section>`)}
function metricsPage(){const ms=periodMetrics().sort((a,b)=>b.date.localeCompare(a.date)),rev=ms.reduce((s,m)=>s+m.revenue,0);return heading('Doanh thu','Ghi nhận số tăng thêm theo ngày, tránh cộng trùng.',`${addBtn('metrics','Nhập số liệu')}<button id="exportCsv">Xuất CSV</button>`)+`<div class="filters"><select id="channelFilter" aria-label="Lọc kênh">${channelOptions()}</select><select id="period" aria-label="Khoảng thời gian">${opts([['month','Tháng này'],['last','Tháng trước'],['all','Tất cả thời gian']],period)}</select></div><div class="stats">${[['Tổng doanh thu',money(rev)],['Đã nhận',money(ms.filter(m=>m.received==='yes').reduce((s,m)=>s+m.revenue,0))],['Chi phí',money(ms.reduce((s,m)=>s+(m.cost||0),0))],['Chênh lệch thu – chi',money(rev-ms.reduce((s,m)=>s+(m.cost||0),0))]].map(([l,n])=>`<div class="stat"><span>${l}</span><strong>${n}</strong></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Sổ ghi chép</h2><span class="muted">${ms.length} dòng</span></div>${ms.length?`<div class="table-wrap"><table><thead><tr><th>Ngày</th><th>Kênh / nguồn thu</th><th class="num">Lượt xem</th><th class="num">Theo dõi mới</th><th class="num">Doanh thu</th><th class="num">Chi phí</th><th>Thanh toán</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr><td>${dateText(m.date)}</td><td>${esc(channelName(m.channelId))}<br><small>${esc(m.source)}</small></td><td class="num">${num(m.views)}</td><td class="num">${num(m.followers)}</td><td class="num">${money(m.revenue)}</td><td class="num">${money(m.cost)}</td><td>${m.received==='yes'?'Đã nhận':'Ước tính'}</td><td><button data-edit="metrics" data-id="${m.id}">Sửa</button></td></tr>`).join('')}<tr><td colspan="4"><strong>Tổng cộng</strong></td><td class="num"><strong>${money(rev)}</strong></td><td class="num">${money(ms.reduce((s,m)=>s+(m.cost||0),0))}</td><td colspan="2"></td></tr></tbody></table></div>`:empty('Chưa có số liệu','Nhập doanh thu, lượt xem và người theo dõi tăng thêm của từng ngày.',addBtn('metrics','Nhập số liệu'))}</section><section class="panel mt"><h2>Doanh thu theo nguồn</h2>${[...new Set(ms.map(m=>m.source))].map(s=>{const total=ms.filter(m=>m.source===s).reduce((a,m)=>a+m.revenue,0);return `<div class="row"><span>${esc(s)}</span><strong>${money(total)}</strong></div>`}).join('')||'<p class="muted mt">Nguồn thu sẽ xuất hiện khi có số liệu.</p>'}</section>`}
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function calendarPage(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-(first.getDay()+6)%7);let days=42;if(calendarMode==='week'){start.setTime(calendarDate.getTime());start.setDate(start.getDate()-(start.getDay()+6)%7);days=7}const scheduled=db.content.filter(c=>c.scheduledAt&&(!filterChannel||c.channelId===filterChannel));return heading('Lịch đăng','Lịch nội bộ của Xưởng. Chưa gửi lịch lên nền tảng.',addBtn('content','Tạo nội dung'))+`<div class="filters"><button id="prevMonth" aria-label="Kỳ trước">‹</button><strong>${calendarMode==='month'?'Tháng '+(m+1)+' / '+y:'Tuần từ '+dateText(localDate(start))}</strong><button id="nextMonth" aria-label="Kỳ sau">›</button><button id="todayCal">Hôm nay</button><button id="calMode">${calendarMode==='month'?'Xem tuần':'Xem tháng'}</button><select id="channelFilter" aria-label="Lọc kênh">${channelOptions()}</select></div><section class="panel"><div class="calendar-scroll"><div class="calendar">${['Thứ hai','Thứ ba','Thứ tư','Thứ năm','Thứ sáu','Thứ bảy','Chủ nhật'].map(s=>`<div class="dayname">${s}</div>`).join('')}${Array.from({length:days},(_,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);let key=localDate(d);return `<div class="day ${key===today()?'today':''}"><span>${d.getDate()}${d.getDate()===1?'/'+(d.getMonth()+1):''}</span>${scheduled.filter(c=>c.scheduledAt.slice(0,10)===key).map(c=>`<button class="cal-item" data-edit="content" data-id="${c.id}">${esc(c.scheduledAt.slice(11,16))} ${esc(c.title)}<br>${statuses[c.status]}</button>`).join('')}</div>`}).join('')}</div></div></section><section class="panel mt"><div class="panel-head"><h2>Đã duyệt, chưa xếp lịch</h2></div>${db.content.filter(c=>c.status==='approved'&&!c.scheduledAt&&(!filterChannel||c.channelId===filterChannel)).map(c=>`<div class="row"><strong>${esc(c.title)}</strong><button data-edit="content" data-id="${c.id}">Xếp lịch</button></div>`).join('')||'<p class="muted">Chưa có bài chờ xếp lịch.</p>'}</section>`}
function settingsPage(){return heading('Cài đặt','Quản lý dữ liệu và trạng thái kết nối.')+`<section class="panel"><h2>Dữ liệu và sao lưu</h2><div class="settings-row"><div><strong>Lưu trên thiết bị</strong><p>Dữ liệu nằm trong trình duyệt này. Chưa có đồng bộ máy chủ hoặc giữa các thiết bị.</p></div><span class="badge approved">Đang dùng</span></div><div class="settings-row"><div><strong>Sao lưu toàn bộ</strong><p>Tải file JSON gồm kênh, nội dung, bộ truyện, câu lệnh và số liệu.</p></div><button id="exportBackup">Tải bản sao lưu</button></div><div class="settings-row"><div><strong>Khôi phục dữ liệu</strong><p>File hợp lệ sẽ thay thế dữ liệu hiện tại sau khi bạn xác nhận.</p></div><button id="importBackup">Nhập sao lưu</button></div><div class="settings-row"><div><strong>Chế độ hiển thị</strong><p>Sáng hoặc tối, ghi nhớ trên thiết bị.</p></div><button id="themeSettings">Đổi chế độ</button></div></section><section class="panel mt"><h2>AI và nền tảng</h2><div class="settings-row"><div><strong>Trợ lý AI</strong><p>Hiện hỗ trợ soạn câu lệnh đầy đủ và sao chép sang AI bạn đang dùng. Dán kết quả vào bài để duyệt.</p></div><span class="badge">Chưa kết nối tự động</span></div>${['Facebook Page','YouTube','Etsy','Pinterest','TikTok'].map(s=>`<div class="settings-row"><div><strong>${s}</strong><p>Đăng thủ công. Chưa cấu hình OAuth và API chính thức.</p></div><span class="badge">Chưa kết nối</span></div>`).join('')}<p class="help-text mt">Không lưu mật khẩu, thông tin ngân hàng hoặc API key trong phiên bản lưu trên trình duyệt. Tự viết theo lịch chưa được kích hoạt.</p></section>`}
function safeLink(url,label){try{let u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '';return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${label}</a>`}catch{return ''}}
function input(name,label,value='',type='text',extra=''){return `<label class="field ${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`}
function select(name,label,options,val){return `<label class="field">${label}<select name="${name}">${opts(options,val)}</select></label>`}
function openEditor(type,id='',defaults={}){if(['content','metrics','series'].includes(type)&&!db.channels.length){toast('Hãy thêm kênh đầu tiên trước.');return}editType=type;editId=id;const o={...(db[type].find(x=>x.id===id)||{}),...defaults};$('#dialogTitle').textContent=(id?'Chỉnh sửa ':'Tạo ')+({content:'nội dung',channels:'kênh',prompts:'câu lệnh',metrics:'số liệu',series:'bộ truyện'}[type]);$('#deleteItem').hidden=!id;$('#editForm button[type="submit"]').disabled=false;$('#deleteItem').disabled=false;let html='';const channels=db.channels.map(x=>[x.id,x.name]);
if(type==='channels')html=input('name','Tên kênh',o.name,'text','required maxlength="150"')+select('platform','Nền tảng',platforms,o.platform||'Facebook')+input('genre','Chủ đề / thể loại',o.genre)+input('link','Link kênh',o.link,'url')+input('style','Giọng văn',o.style,'textarea')+input('visual','Phong cách hình ảnh',o.visual,'textarea');
if(type==='prompts')html=input('name','Tên mẫu',o.name,'text','required maxlength="150"')+input('text','Câu lệnh (dùng {tên biến} để cá nhân hóa)',o.text,'textarea','required');
if(type==='series')html=input('title','Tên bộ truyện',o.title,'text','required maxlength="200"')+select('channelId','Kênh',channels,o.channelId||db.channels[0].id)+select('exclusivity','Trạng thái độc quyền',['Không độc quyền','Độc quyền Webnovel','Độc quyền Kindle Unlimited','Độc quyền khác'],o.exclusivity||'Không độc quyền')+input('chapterLength','Số từ mỗi chương',o.chapterLength||1500,'number','min="100" max="100000" step="1"')+input('schedule','Kế hoạch ra chương',o.schedule)+input('outline','Dàn ý',o.outline,'textarea')+input('characters','Hồ sơ nhân vật',o.characters,'textarea');
if(type==='metrics')html=input('date','Ngày ghi nhận',o.date||today(),'date','required')+select('channelId','Kênh',channels,o.channelId||db.channels[0].id)+`<label class="field">Nguồn thu<input name="source" list="sourceList" value="${esc(o.source||defaultSource(ch(o.channelId||db.channels[0].id)?.platform))}" required><datalist id="sourceList">${db.sources.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></label>`+select('received','Tình trạng tiền',[['no','Ước tính / chưa nhận'],['yes','Đã nhận']],o.received||'no')+input('views','Lượt xem tăng thêm trong ngày',o.views||0,'number','min="0" step="1" required')+input('followers','Người theo dõi mới trong ngày',o.followers||0,'number','min="0" step="1" required')+input('revenue','Doanh thu (VND)',o.revenue||0,'number','min="0" step="1" required')+input('cost','Chi phí (VND)',o.cost||0,'number','min="0" step="1" required')+input('note','Ghi chú',o.note,'textarea');
if(type==='content')html=input('title','Tiêu đề',o.title,'text','required maxlength="250"')+select('channelId','Kênh',channels,o.channelId||db.channels[0].id)+select('status','Trạng thái',Object.entries(statuses),o.status||'idea')+select('seriesId','Bộ truyện (nếu có)',[['','Không thuộc bộ truyện'],...db.series.filter(s=>s.channelId===(o.channelId||db.channels[0].id)).map(s=>[s.id,s.title])],o.seriesId||'')+input('prompt','Câu lệnh viết nội dung',o.prompt,'textarea')+`<div class="helper"><strong>Viết cùng AI</strong><p>Sao chép câu lệnh kèm ngữ cảnh kênh và bộ truyện, gửi vào AI, rồi dán kết quả vào nội dung bên dưới.</p><div class="actions mt"><button type="button" id="copyPrompt">Sao chép câu lệnh đầy đủ</button><button type="button" id="imagePrompt">Soạn câu lệnh ảnh</button></div></div>`+input('body','Nội dung',o.body,'textarea','class="body"')+input('imagePrompt','Câu lệnh hình ảnh (English)',o.imagePrompt,'textarea')+input('scheduledAt','Ngày giờ đăng (giờ trên thiết bị)',o.scheduledAt,'datetime-local')+input('link','Link bài đã đăng',o.link,'url')+`<div class="helper">Chỉ xếp lịch cho bài đã duyệt. Để đánh dấu đã đăng, bài phải được duyệt trước và có link bài. Lịch này chưa tự đăng lên nền tảng.</div>`;
$('#fields').innerHTML=html;if(!$('#editor').open)$('#editor').showModal();$('#fields input, #fields textarea')?.focus()}
function defaultSource(p){return({Facebook:'Quảng cáo Facebook',Etsy:'Etsy',Pinterest:'Pinterest / Affiliate',YouTube:'YouTube',TikTok:'TikTok','Web truyện':'Truyện đọc (chương trả phí)',Webtoon:'Webtoon'})[p]||'Khác'}
function formValue(){return Object.fromEntries(new FormData($('#editForm')))}
function fullPrompt(){const d=formValue(),c=ch(d.channelId),s=db.series.find(s=>s.id===d.seriesId),prior=s?db.content.filter(x=>x.seriesId===s.id&&x.id!==editId&&x.body).sort((a,b)=>a.createdAt.localeCompare(b.createdAt)).at(-1):null;return ['Nhiệm vụ: '+(d.prompt||'Viết nội dung cho: '+d.title),'Tiêu đề: '+d.title,'Kênh: '+c?.name,'Nền tảng: '+c?.platform,'Chủ đề: '+(c?.genre||''),'Giọng văn: '+(c?.style||''),s?'Bộ truyện: '+s.title+'\nDàn ý: '+s.outline+'\nNhân vật: '+s.characters+'\nĐộ dài chương: '+s.chapterLength+' từ':'',prior?'Chương trước (nguyên văn):\n'+prior.body:'','Chỉ viết nội dung để người dùng duyệt. Không tự đăng. Không bịa dữ kiện.'].filter(Boolean).join('\n\n')}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Đã sao chép')}catch{toast('Trình duyệt chặn clipboard. Câu lệnh đã được đưa vào ô để bạn sao chép.');const t=$('[name="prompt"]');if(t){t.value=s;t.focus();t.select()}}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){download('xuong-noi-dung-'+today()+'.json',JSON.stringify(db,null,2),'application/json');toast('Đã xuất bản sao lưu')}
$('#editForm').addEventListener('submit',e=>{e.preventDefault();const d=formValue(),old=db[editType].find(x=>x.id===editId),now=new Date().toISOString();for(const k of Object.keys(d))d[k]=d[k].trim();if(editType==='content'){if(!ch(d.channelId))return toast('Kênh không tồn tại');if(d.seriesId&&!db.series.some(s=>s.id===d.seriesId&&s.channelId===d.channelId))return toast('Bộ truyện phải thuộc kênh đã chọn');if(['review','approved','live'].includes(d.status)&&!d.body)return toast('Cần có nội dung trước khi gửi duyệt');if(d.scheduledAt&&!['approved','live'].includes(d.status))return toast('Hãy chuyển sang Đã duyệt trước khi xếp lịch');if(d.status==='live'&&(!old||!['approved','live'].includes(old.status)))return toast('Hãy lưu trạng thái Đã duyệt trước, sau đó xác nhận Đã đăng');if(d.status==='live'&&!d.link)return toast('Cần link bài đã đăng');d.createdAt=old?.createdAt||now;d.updatedAt=now;d.publishedAt=d.status==='live'?(old?.publishedAt||now):null}
if(editType==='metrics'){for(const k of ['views','followers','revenue','cost']){d[k]=Number(d[k]);if(!Number.isSafeInteger(d[k])||d[k]<0)return toast('Số liệu phải là số nguyên không âm')}if(!db.sources.includes(d.source))db.sources.push(d.source)}if(editType==='series')d.chapterLength=Number(d.chapterLength);const item={...old,...d,id:editId||uid()};const before=JSON.stringify(db);if(editId)db[editType]=db[editType].map(x=>x.id===editId?item:x);else db[editType].push(item);if(!save()){db=JSON.parse(before);return}closedDraft=null;$('#resumeDraft')?.remove();$('#editor').close();toast('Đã lưu '+({content:'nội dung',channels:'kênh',metrics:'số liệu',series:'bộ truyện',prompts:'câu lệnh'}[editType]));render()});
$('#deleteItem').onclick=async()=>{if(editType==='channels'&&(db.content.some(c=>c.channelId===editId)||db.metrics.some(c=>c.channelId===editId)||db.series.some(c=>c.channelId===editId)))return toast('Kênh đang có dữ liệu. Hãy chuyển hoặc xóa dữ liệu liên quan trước.');if(editType==='series'&&db.content.some(c=>c.seriesId===editId))return toast('Bộ truyện đang có chương. Hãy bỏ liên kết chương trước.');if(!await uiConfirm('Xóa mục này? Thao tác không thể hoàn tác.'))return;const before=JSON.stringify(db);db[editType]=db[editType].filter(x=>x.id!==editId);if(!save()){db=JSON.parse(before);return}$('#editor').close();render();toast('Đã xóa')};
let closedDraft=null;
function closeEditor(){closedDraft={type:editType,id:editId,data:formValue()};$('#editor').close();toast('Đã đóng. Bản nháp chưa lưu có thể mở lại ở thanh trên.');showResumeDraft()}
function showResumeDraft(){let b=$('#resumeDraft');if(!b){b=document.createElement('button');b.id='resumeDraft';b.textContent='Mở lại bản nháp';$('header').append(b)}b.onclick=()=>{if(closedDraft)openEditor(closedDraft.type,closedDraft.id,closedDraft.data)};b.hidden=!closedDraft}
$('#closeDialog').onclick=$('#cancelDialog').onclick=closeEditor;$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor()});
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-go]');if(!el)return;if(el.dataset.new)openEditor(el.dataset.new);if(el.dataset.edit)openEditor(el.dataset.edit,el.dataset.id);if(el.dataset.go)location.hash=el.dataset.go;if(el.dataset.use){const p=db.prompts.find(p=>p.id===el.dataset.use);let text=p.text;openEditor('content','',{prompt:text,status:'idea'})}if(el.dataset.chapter){const s=db.series.find(s=>s.id===el.dataset.chapter);openEditor('content','',{title:'Chương '+(db.content.filter(c=>c.seriesId===s.id).length+1),channelId:s.channelId,seriesId:s.id,status:'draft',prompt:'Viết chương tiếp theo theo dàn ý và hồ sơ nhân vật.'})}if(el.id==='toggleMode'){mode=mode==='board'?'list':'board';render()}if(['exportBackup','backupSide'].includes(el.id))backup();if(el.id==='importBackup')$('#importFile').click();if(['theme','themeSettings'].includes(el.id)){document.documentElement.classList.toggle('dark');try{localStorage.setItem('xuong-theme',document.documentElement.classList.contains('dark')?'dark':'light')}catch{}}if(el.id==='menu')document.body.classList.toggle('menu-open');if(el.id==='copyPrompt')copy(fullPrompt());if(el.id==='imagePrompt'){const d=formValue(),c=ch(d.channelId);$('[name="imagePrompt"]').value=`Create one ${c?.platform==='Pinterest'?'vertical 2:3':'standalone'} image for ${c?.platform||'the selected channel'}.\nScene / subject (translate the supplied content into English when generating):\n${d.title}\n${(d.body||'').slice(0,2000)}\nVisual direction: ${c?.visual||'Follow the actual subject and setting.'}\nDo not invent unsupported events, people or claims. No watermark. This is an image-generation instruction, not a generated image.`;toast('Đã soạn câu lệnh ảnh. Bạn có thể chỉnh trước khi gửi AI.')}if(el.id==='prevMonth'||el.id==='nextMonth'){let n=el.id==='prevMonth'?-1:1;if(calendarMode==='month'){calendarDate.setDate(1);calendarDate.setMonth(calendarDate.getMonth()+n)}else calendarDate.setDate(calendarDate.getDate()+7*n);render()}if(el.id==='todayCal'){calendarDate=new Date;render()}if(el.id==='calMode'){calendarMode=calendarMode==='month'?'week':'month';render()}if(el.id==='exportCsv'){const rows=[['Ngày','Kênh','Nguồn','Lượt xem mới','Theo dõi mới','Doanh thu VND','Chi phí VND','Đã nhận','Ghi chú'],...periodMetrics().map(m=>[m.date,channelName(m.channelId),m.source,m.views,m.followers,m.revenue,m.cost,m.received==='yes'?'Có':'Không',m.note])];download('doanh-thu-'+today()+'.csv','\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}});
document.addEventListener('change',e=>{if(e.target.id==='channelFilter'){filterChannel=e.target.value;render()}if(e.target.id==='statusFilter'){filterStatus=e.target.value;render()}if(e.target.id==='period'){period=e.target.value;render()}if(e.target.name==='channelId'&&$('#editor').open){const channelId=e.target.value;if(editType==='content'){$('[name="seriesId"]').innerHTML=opts([['','Không thuộc bộ truyện'],...db.series.filter(s=>s.channelId===channelId).map(s=>[s.id,s.title])],'')}if(editType==='metrics')$('[name="source"]').value=defaultSource(ch(channelId)?.platform)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15000000)throw Error('File vượt quá 15 MB');const v=JSON.parse(await file.text());validate(v);for(const c of v.channels)if(typeof c.name!=='string'||!platforms.includes(c.platform))throw Error('Kênh không hợp lệ');const channels=new Set(v.channels.map(c=>c.id)),series=new Set(v.series.map(s=>s.id));for(const list of [v.content,v.metrics,v.series])for(const r of list)if(!channels.has(r.channelId))throw Error('Có dữ liệu tham chiếu kênh không tồn tại');for(const c of v.content)if(c.seriesId&&!series.has(c.seriesId))throw Error('Có chương tham chiếu truyện không tồn tại');if(!await uiConfirm('Thay thế toàn bộ dữ liệu hiện tại bằng bản sao lưu? Nên tải bản sao lưu hiện tại trước.'))return;const before=db,previousError=loadError;db=v;loadError=false;if(!save()){db=before;loadError=previousError;return}filterChannel='';filterStatus='';render();toast('Đã khôi phục dữ liệu')}catch(err){toast('Không nhập được: '+err.message)}finally{e.target.value=''}};
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);document.body.classList.remove('menu-open');render();window.scrollTo(0,0)});window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const v=JSON.parse(e.newValue);validate(v);if($('#editor').open){toast('Dữ liệu đã thay đổi ở tab khác. Đóng trình soạn và tải lại trước khi sửa tiếp.');$('#editForm button[type="submit"]').disabled=true;$('#deleteItem').disabled=true;return}db=v;render()}catch{toast('Dữ liệu ở tab khác không hợp lệ')}}});try{document.documentElement.classList.toggle('dark',localStorage.getItem('xuong-theme')==='dark')}catch{}render();if(loadError)toast('Không đọc được dữ liệu đã lưu. Dữ liệu cũ chưa bị ghi đè; hãy kiểm tra sao lưu trước khi thêm mới.');
